CREATE OR REPLACE FUNCTION public.add_specialist_to_customers()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_email text;
BEGIN
  IF NEW.email IS NULL OR NEW.email = '' THEN
    RETURN NEW;
  END IF;
  IF NEW.is_active IS NOT TRUE THEN
    RETURN NEW;
  END IF;
  v_email := NEW.email;

  INSERT INTO public.automatic_orders (
    customer_name, customer_email, customer_phone, package_name, package_type,
    amount, payment_method, customer_type, registration_date, monthly_payment_day,
    total_months, paid_months, is_active, customer_city
  )
  SELECT
    NEW.name, v_email, COALESCE(NEW.phone, '0 216 706 06 11'),
    COALESCE(NEW.specialty, 'Uzman') || ' Paketi',
    LOWER(REPLACE(COALESCE(NEW.specialty, 'uzman'), ' ', '_')),
    COALESCE(NEW.package_price, 3000),
    'banka_havalesi', 'individual', NOW(),
    COALESCE(NEW.payment_day, 1), 24,
    ARRAY[]::integer[], true, NEW.city
  WHERE NOT EXISTS (
    SELECT 1 FROM public.automatic_orders ao WHERE ao.customer_email = v_email
  );

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.admin_update_client_referral_notes(p_specialist_id uuid, p_year integer, p_month integer, p_notes text)
 RETURNS client_referrals
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_row public.client_referrals;
BEGIN
  -- Only allow admin or staff
  IF NOT (public.is_admin_user() OR public.is_admin_or_staff_user()) THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;

  INSERT INTO public.client_referrals (
    specialist_id, year, month, referral_count, notes, updated_at
  ) VALUES (
    p_specialist_id, p_year, p_month, 0, p_notes, now()
  )
  ON CONFLICT (specialist_id, year, month)
  DO UPDATE SET
    notes = EXCLUDED.notes,
    updated_at = now()
  RETURNING * INTO v_row;

  RETURN v_row;
END;
$function$

CREATE OR REPLACE FUNCTION public.admin_update_specialist_slug(p_specialist_id uuid, p_new_slug text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id uuid;
  v_role text;
  v_clean_slug text;
  v_exists boolean;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Yetkisiz: oturum yok');
  END IF;

  SELECT role INTO v_role FROM public.user_profiles WHERE user_id = v_user_id LIMIT 1;
  IF v_role IS NULL OR v_role <> 'admin' THEN
    RETURN jsonb_build_object('success', false, 'error', 'Yalnızca admin kullanıcılar profil linkini değiştirebilir');
  END IF;

  -- Temizle: küçük harf, türkçe karakterler dönüştür, sadece a-z 0-9 ve tire
  v_clean_slug := lower(trim(p_new_slug));
  v_clean_slug := translate(v_clean_slug, 'ışğüöçâîû', 'isguocaiu');
  v_clean_slug := regexp_replace(v_clean_slug, '[^a-z0-9\s-]', '', 'g');
  v_clean_slug := regexp_replace(v_clean_slug, '\s+', '-', 'g');
  v_clean_slug := regexp_replace(v_clean_slug, '-+', '-', 'g');
  v_clean_slug := trim(both '-' from v_clean_slug);

  IF v_clean_slug = '' OR length(v_clean_slug) < 3 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Geçersiz slug (en az 3 karakter olmalı)');
  END IF;

  SELECT EXISTS (
    SELECT 1 FROM public.specialists
    WHERE slug = v_clean_slug AND id <> p_specialist_id
  ) INTO v_exists;

  IF v_exists THEN
    RETURN jsonb_build_object('success', false, 'error', 'Bu link başka bir uzman tarafından kullanılıyor');
  END IF;

  -- preserve_specialist_slug trigger'ını bypass etmek için triggeri geçici devre dışı bırak
  ALTER TABLE public.specialists DISABLE TRIGGER trg_preserve_specialist_slug;
  UPDATE public.specialists SET slug = v_clean_slug WHERE id = p_specialist_id;
  ALTER TABLE public.specialists ENABLE TRIGGER trg_preserve_specialist_slug;

  RETURN jsonb_build_object('success', true, 'slug', v_clean_slug);
END;
$function$

CREATE OR REPLACE FUNCTION public.block_appointments_from_blocked_visitors()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_ip text;
BEGIN
  v_ip := public.client_ip_from_headers();
  IF (NEW.ip_address IS NULL OR btrim(coalesce(NEW.ip_address, '')) = '') AND v_ip IS NOT NULL THEN
    NEW.ip_address := v_ip;
  END IF;

  -- Mevcut kayitlarin guncellenmesi (onay/iptal/tamamlandi) engellenmez.
  IF TG_OP <> 'INSERT' THEN
    RETURN NEW;
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.blocked_visitors bv
    WHERE (bv.email IS NOT NULL AND lower(bv.email) = lower(coalesce(NEW.patient_email, '')))
       OR (bv.full_name IS NOT NULL
           AND btrim(bv.full_name) <> ''
           AND lower(regexp_replace(bv.full_name, '\s+', ' ', 'g'))
             = lower(regexp_replace(btrim(coalesce(NEW.patient_name, '')), '\s+', ' ', 'g')))
       OR (bv.phone IS NOT NULL
           AND public.normalize_phone_digits(bv.phone) <> ''
           AND public.normalize_phone_digits(bv.phone) = public.normalize_phone_digits(NEW.patient_phone))
       OR (bv.ip_address IS NOT NULL AND btrim(bv.ip_address) <> ''
           AND NEW.ip_address IS NOT NULL AND btrim(NEW.ip_address) <> ''
           AND bv.ip_address = NEW.ip_address)
  ) THEN
    RAISE EXCEPTION 'blocked_visitor: randevu olusturma izni yok';
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.can_manage_users(target_user_id uuid DEFAULT NULL::uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  current_user_role TEXT;
  current_user_approved BOOLEAN;
BEGIN
  -- Mevcut kullanıcının rolünü ve onay durumunu al
  SELECT role::text, is_approved INTO current_user_role, current_user_approved
  FROM public.user_profiles 
  WHERE user_id = auth.uid();

  -- Admin veya staff ise ve onaylı ise işlem yapabilir
  IF current_user_role IN ('admin', 'staff') AND current_user_approved = true THEN
    RETURN true;
  END IF;

  RETURN false;
EXCEPTION
  WHEN OTHERS THEN
    RETURN false;
END;
$function$

CREATE OR REPLACE FUNCTION public.check_admin_login_block(p_email text)
 RETURNS TABLE(is_blocked boolean, blocked_until timestamp with time zone, attempts_remaining integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_record RECORD;
BEGIN
  SELECT * INTO v_record 
  FROM public.admin_login_attempts 
  WHERE email = LOWER(p_email);

  IF NOT FOUND THEN
    RETURN QUERY SELECT false, NULL::TIMESTAMPTZ, 3;
    RETURN;
  END IF;

  -- Check if block has expired
  IF v_record.is_blocked AND v_record.blocked_until IS NOT NULL THEN
    IF v_record.blocked_until <= NOW() THEN
      -- Block expired, reset the record
      UPDATE public.admin_login_attempts 
      SET is_blocked = false, 
          attempt_count = 0, 
          blocked_until = NULL,
          last_attempt_at = NOW()
      WHERE email = LOWER(p_email);

      RETURN QUERY SELECT false, NULL::TIMESTAMPTZ, 3;
      RETURN;
    ELSE
      -- Still blocked
      RETURN QUERY SELECT true, v_record.blocked_until, 0;
      RETURN;
    END IF;
  END IF;

  -- Not blocked, return remaining attempts
  RETURN QUERY SELECT false, NULL::TIMESTAMPTZ, GREATEST(0, 3 - v_record.attempt_count)::INTEGER;
END;
$function$

CREATE OR REPLACE FUNCTION public.cleanup_old_backups()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_old_backup record;
  v_backup_suffix text;
  v_table_name text;
BEGIN
  FOR v_old_backup IN 
    SELECT id, backup_timestamp FROM public.database_backups 
    WHERE backup_timestamp < NOW() - INTERVAL '3 days'
  LOOP
    v_backup_suffix := EXTRACT(EPOCH FROM v_old_backup.backup_timestamp)::bigint::text;

    FOR v_table_name IN 
      SELECT t.table_name 
      FROM information_schema.tables t
      WHERE t.table_schema = 'public' 
      AND t.table_name LIKE 'backup_' || v_backup_suffix || '_%'
    LOOP
      EXECUTE 'DROP TABLE IF EXISTS public.' || quote_ident(v_table_name);
    END LOOP;

    DELETE FROM public.database_backups WHERE id = v_old_backup.id;
  END LOOP;
END;
$function$

CREATE OR REPLACE FUNCTION public.create_full_database_backup(p_backup_type text DEFAULT 'automatic'::text, p_created_by uuid DEFAULT NULL::uuid, p_notes text DEFAULT NULL::text)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE
  v_backup_id bigint;
  v_backup_timestamp timestamptz := NOW();
  v_backup_suffix text;
  v_total_records integer := 0;
  v_tables_backed_up text[] := '{}';
  v_record_count integer;
  v_backup_table text;
BEGIN
  -- Never use current_user here: SECURITY DEFINER makes it the owner.
  -- Direct postgres cron job 23 is preserved; PostgREST SET ROLE cannot pass this branch.
  IF NOT (
    current_setting('role', true) = 'service_role'
    OR (session_user = 'postgres' AND current_setting('role', true) IN ('none', 'postgres')
        AND auth.uid() IS NULL)
    OR (current_setting('role', true) = 'authenticated' AND public.is_admin_user())
  ) THEN
    RAISE EXCEPTION 'Forbidden: approved admin or trusted database scheduler required'
      USING ERRCODE = '42501';
  END IF;
  IF current_setting('role', true) = 'authenticated' THEN
    p_created_by := auth.uid();
  END IF;
  v_backup_suffix := EXTRACT(EPOCH FROM v_backup_timestamp)::bigint::text;

  INSERT INTO public.database_backups (backup_type, backup_status, created_by, notes)
  VALUES (p_backup_type, 'in_progress', p_created_by, p_notes)
  RETURNING id INTO v_backup_id;

  -- Macro to backup a table and enable RLS
  -- Backup specialists
  v_backup_table := 'backup_' || v_backup_suffix || '_specialists';
  EXECUTE 'CREATE TABLE public.' || quote_ident(v_backup_table) || ' AS TABLE public.specialists';
  GET DIAGNOSTICS v_record_count = ROW_COUNT;
  EXECUTE 'GRANT SELECT ON public.' || quote_ident(v_backup_table) || ' TO authenticated';
  EXECUTE 'GRANT ALL ON public.' || quote_ident(v_backup_table) || ' TO service_role';
  v_total_records := v_total_records + v_record_count;
  v_tables_backed_up := array_append(v_tables_backed_up, 'specialists');
  EXECUTE 'ALTER TABLE public.' || quote_ident(v_backup_table) || ' ENABLE ROW LEVEL SECURITY';
  EXECUTE 'CREATE POLICY "Admin only access" ON public.' || quote_ident(v_backup_table) || ' FOR ALL TO authenticated USING (public.is_admin_user())';

  -- Backup client_referrals
  v_backup_table := 'backup_' || v_backup_suffix || '_client_referrals';
  EXECUTE 'CREATE TABLE public.' || quote_ident(v_backup_table) || ' AS TABLE public.client_referrals';
  GET DIAGNOSTICS v_record_count = ROW_COUNT;
  EXECUTE 'GRANT SELECT ON public.' || quote_ident(v_backup_table) || ' TO authenticated';
  EXECUTE 'GRANT ALL ON public.' || quote_ident(v_backup_table) || ' TO service_role';
  v_total_records := v_total_records + v_record_count;
  v_tables_backed_up := array_append(v_tables_backed_up, 'client_referrals');
  EXECUTE 'ALTER TABLE public.' || quote_ident(v_backup_table) || ' ENABLE ROW LEVEL SECURITY';
  EXECUTE 'CREATE POLICY "Admin only access" ON public.' || quote_ident(v_backup_table) || ' FOR ALL TO authenticated USING (public.is_admin_user())';

  -- Backup orders
  v_backup_table := 'backup_' || v_backup_suffix || '_orders';
  EXECUTE 'CREATE TABLE public.' || quote_ident(v_backup_table) || ' AS TABLE public.orders';
  GET DIAGNOSTICS v_record_count = ROW_COUNT;
  EXECUTE 'GRANT SELECT ON public.' || quote_ident(v_backup_table) || ' TO authenticated';
  EXECUTE 'GRANT ALL ON public.' || quote_ident(v_backup_table) || ' TO service_role';
  v_total_records := v_total_records + v_record_count;
  v_tables_backed_up := array_append(v_tables_backed_up, 'orders');
  EXECUTE 'ALTER TABLE public.' || quote_ident(v_backup_table) || ' ENABLE ROW LEVEL SECURITY';
  EXECUTE 'CREATE POLICY "Admin only access" ON public.' || quote_ident(v_backup_table) || ' FOR ALL TO authenticated USING (public.is_admin_user())';

  -- Backup automatic_orders
  v_backup_table := 'backup_' || v_backup_suffix || '_automatic_orders';
  EXECUTE 'CREATE TABLE public.' || quote_ident(v_backup_table) || ' AS TABLE public.automatic_orders';
  GET DIAGNOSTICS v_record_count = ROW_COUNT;
  EXECUTE 'GRANT SELECT ON public.' || quote_ident(v_backup_table) || ' TO authenticated';
  EXECUTE 'GRANT ALL ON public.' || quote_ident(v_backup_table) || ' TO service_role';
  v_total_records := v_total_records + v_record_count;
  v_tables_backed_up := array_append(v_tables_backed_up, 'automatic_orders');
  EXECUTE 'ALTER TABLE public.' || quote_ident(v_backup_table) || ' ENABLE ROW LEVEL SECURITY';
  EXECUTE 'CREATE POLICY "Admin only access" ON public.' || quote_ident(v_backup_table) || ' FOR ALL TO authenticated USING (public.is_admin_user())';

  -- Backup appointments
  v_backup_table := 'backup_' || v_backup_suffix || '_appointments';
  EXECUTE 'CREATE TABLE public.' || quote_ident(v_backup_table) || ' AS TABLE public.appointments';
  GET DIAGNOSTICS v_record_count = ROW_COUNT;
  EXECUTE 'GRANT SELECT ON public.' || quote_ident(v_backup_table) || ' TO authenticated';
  EXECUTE 'GRANT ALL ON public.' || quote_ident(v_backup_table) || ' TO service_role';
  v_total_records := v_total_records + v_record_count;
  v_tables_backed_up := array_append(v_tables_backed_up, 'appointments');
  EXECUTE 'ALTER TABLE public.' || quote_ident(v_backup_table) || ' ENABLE ROW LEVEL SECURITY';
  EXECUTE 'CREATE POLICY "Admin only access" ON public.' || quote_ident(v_backup_table) || ' FOR ALL TO authenticated USING (public.is_admin_user())';

  -- Backup blog_posts
  v_backup_table := 'backup_' || v_backup_suffix || '_blog_posts';
  EXECUTE 'CREATE TABLE public.' || quote_ident(v_backup_table) || ' AS TABLE public.blog_posts';
  GET DIAGNOSTICS v_record_count = ROW_COUNT;
  EXECUTE 'GRANT SELECT ON public.' || quote_ident(v_backup_table) || ' TO authenticated';
  EXECUTE 'GRANT ALL ON public.' || quote_ident(v_backup_table) || ' TO service_role';
  v_total_records := v_total_records + v_record_count;
  v_tables_backed_up := array_append(v_tables_backed_up, 'blog_posts');
  EXECUTE 'ALTER TABLE public.' || quote_ident(v_backup_table) || ' ENABLE ROW LEVEL SECURITY';
  EXECUTE 'CREATE POLICY "Admin only access" ON public.' || quote_ident(v_backup_table) || ' FOR ALL TO authenticated USING (public.is_admin_user())';

  -- Backup reviews
  v_backup_table := 'backup_' || v_backup_suffix || '_reviews';
  EXECUTE 'CREATE TABLE public.' || quote_ident(v_backup_table) || ' AS TABLE public.reviews';
  GET DIAGNOSTICS v_record_count = ROW_COUNT;
  EXECUTE 'GRANT SELECT ON public.' || quote_ident(v_backup_table) || ' TO authenticated';
  EXECUTE 'GRANT ALL ON public.' || quote_ident(v_backup_table) || ' TO service_role';
  v_total_records := v_total_records + v_record_count;
  v_tables_backed_up := array_append(v_tables_backed_up, 'reviews');
  EXECUTE 'ALTER TABLE public.' || quote_ident(v_backup_table) || ' ENABLE ROW LEVEL SECURITY';
  EXECUTE 'CREATE POLICY "Admin only access" ON public.' || quote_ident(v_backup_table) || ' FOR ALL TO authenticated USING (public.is_admin_user())';

  -- Backup tests
  v_backup_table := 'backup_' || v_backup_suffix || '_tests';
  EXECUTE 'CREATE TABLE public.' || quote_ident(v_backup_table) || ' AS TABLE public.tests';
  GET DIAGNOSTICS v_record_count = ROW_COUNT;
  EXECUTE 'GRANT SELECT ON public.' || quote_ident(v_backup_table) || ' TO authenticated';
  EXECUTE 'GRANT ALL ON public.' || quote_ident(v_backup_table) || ' TO service_role';
  v_total_records := v_total_records + v_record_count;
  v_tables_backed_up := array_append(v_tables_backed_up, 'tests');
  EXECUTE 'ALTER TABLE public.' || quote_ident(v_backup_table) || ' ENABLE ROW LEVEL SECURITY';
  EXECUTE 'CREATE POLICY "Admin only access" ON public.' || quote_ident(v_backup_table) || ' FOR ALL TO authenticated USING (public.is_admin_user())';

  -- Backup test_questions
  v_backup_table := 'backup_' || v_backup_suffix || '_test_questions';
  EXECUTE 'CREATE TABLE public.' || quote_ident(v_backup_table) || ' AS TABLE public.test_questions';
  GET DIAGNOSTICS v_record_count = ROW_COUNT;
  EXECUTE 'GRANT SELECT ON public.' || quote_ident(v_backup_table) || ' TO authenticated';
  EXECUTE 'GRANT ALL ON public.' || quote_ident(v_backup_table) || ' TO service_role';
  v_total_records := v_total_records + v_record_count;
  v_tables_backed_up := array_append(v_tables_backed_up, 'test_questions');
  EXECUTE 'ALTER TABLE public.' || quote_ident(v_backup_table) || ' ENABLE ROW LEVEL SECURITY';
  EXECUTE 'CREATE POLICY "Admin only access" ON public.' || quote_ident(v_backup_table) || ' FOR ALL TO authenticated USING (public.is_admin_user())';

  -- Backup test_results
  v_backup_table := 'backup_' || v_backup_suffix || '_test_results';
  EXECUTE 'CREATE TABLE public.' || quote_ident(v_backup_table) || ' AS TABLE public.test_results';
  GET DIAGNOSTICS v_record_count = ROW_COUNT;
  EXECUTE 'GRANT SELECT ON public.' || quote_ident(v_backup_table) || ' TO authenticated';
  EXECUTE 'GRANT ALL ON public.' || quote_ident(v_backup_table) || ' TO service_role';
  v_total_records := v_total_records + v_record_count;
  v_tables_backed_up := array_append(v_tables_backed_up, 'test_results');
  EXECUTE 'ALTER TABLE public.' || quote_ident(v_backup_table) || ' ENABLE ROW LEVEL SECURITY';
  EXECUTE 'CREATE POLICY "Admin only access" ON public.' || quote_ident(v_backup_table) || ' FOR ALL TO authenticated USING (public.is_admin_user())';

  -- Backup packages
  v_backup_table := 'backup_' || v_backup_suffix || '_packages';
  EXECUTE 'CREATE TABLE public.' || quote_ident(v_backup_table) || ' AS TABLE public.packages';
  GET DIAGNOSTICS v_record_count = ROW_COUNT;
  EXECUTE 'GRANT SELECT ON public.' || quote_ident(v_backup_table) || ' TO authenticated';
  EXECUTE 'GRANT ALL ON public.' || quote_ident(v_backup_table) || ' TO service_role';
  v_total_records := v_total_records + v_record_count;
  v_tables_backed_up := array_append(v_tables_backed_up, 'packages');
  EXECUTE 'ALTER TABLE public.' || quote_ident(v_backup_table) || ' ENABLE ROW LEVEL SECURITY';
  EXECUTE 'CREATE POLICY "Admin only access" ON public.' || quote_ident(v_backup_table) || ' FOR ALL TO authenticated USING (public.is_admin_user())';

  -- Backup user_profiles
  v_backup_table := 'backup_' || v_backup_suffix || '_user_profiles';
  EXECUTE 'CREATE TABLE public.' || quote_ident(v_backup_table) || ' AS TABLE public.user_profiles';
  GET DIAGNOSTICS v_record_count = ROW_COUNT;
  EXECUTE 'GRANT SELECT ON public.' || quote_ident(v_backup_table) || ' TO authenticated';
  EXECUTE 'GRANT ALL ON public.' || quote_ident(v_backup_table) || ' TO service_role';
  v_total_records := v_total_records + v_record_count;
  v_tables_backed_up := array_append(v_tables_backed_up, 'user_profiles');
  EXECUTE 'ALTER TABLE public.' || quote_ident(v_backup_table) || ' ENABLE ROW LEVEL SECURITY';
  EXECUTE 'CREATE POLICY "Admin only access" ON public.' || quote_ident(v_backup_table) || ' FOR ALL TO authenticated USING (public.is_admin_user())';

  UPDATE public.database_backups
  SET backup_status = 'completed',
      backup_timestamp = v_backup_timestamp,
      tables_backed_up = v_tables_backed_up,
      total_records = v_total_records
  WHERE id = v_backup_id;

  RAISE NOTICE 'Full database backup completed: % tables, % records', array_length(v_tables_backed_up, 1), v_total_records;

  RETURN v_backup_id;
EXCEPTION
  WHEN OTHERS THEN
    UPDATE public.database_backups
    SET backup_status = 'failed',
        notes = COALESCE(notes || ' | ', '') || 'Error: ' || SQLERRM
    WHERE id = v_backup_id;
    RAISE EXCEPTION 'Backup failed: %', SQLERRM;
END;
$function$

CREATE OR REPLACE FUNCTION public.create_referral_record_on_signup()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_referrer_id uuid;
  v_code text;
BEGIN
  IF NEW.referral_signup_code IS NULL OR length(trim(NEW.referral_signup_code)) = 0 THEN
    RETURN NEW;
  END IF;

  v_code := upper(trim(NEW.referral_signup_code));

  SELECT specialist_id INTO v_referrer_id
  FROM public.specialist_referral_codes
  WHERE code = v_code
  LIMIT 1;

  IF v_referrer_id IS NULL OR v_referrer_id = NEW.id THEN
    RETURN NEW;
  END IF;

  INSERT INTO public.specialist_referrals (
    referrer_specialist_id,
    referred_specialist_id,
    referral_code,
    status
  ) VALUES (
    v_referrer_id,
    NEW.id,
    v_code,
    'pending'
  )
  ON CONFLICT DO NOTHING;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.create_test_ad_visit()
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_sid text := 'test_' || gen_random_uuid()::text;
  v_touch jsonb := jsonb_build_object('utm_source','meta','utm_medium','paid','utm_campaign','TEST_CAMPAIGN',
    'utm_content','TEST_AD','meta_campaign_id','111111','meta_adset_id','222222','meta_ad_id','333333',
    'landing_page','/kayit-ol','at', now());
  ev text;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM user_profiles x WHERE x.user_id = auth.uid() AND x.role = 'admin') THEN
    RAISE EXCEPTION 'yetkisiz';
  END IF;
  INSERT INTO lead_attribution(anonymous_session_id, first_touch, last_touch, is_test) VALUES (v_sid, v_touch, v_touch, true);
  FOREACH ev IN ARRAY ARRAY['landing_page_view','registration_started','registration_completed','checkout_started'] LOOP
    INSERT INTO analytics_events(event_id, anonymous_session_id, event_name, event_properties, utm_source, utm_campaign,
      utm_content, meta_campaign_id, meta_adset_id, meta_ad_id, is_test)
    VALUES (gen_random_uuid()::text, v_sid, ev, '{"test":true}', 'meta', 'TEST_CAMPAIGN', 'TEST_AD', '111111', '222222', '333333', true);
  END LOOP;
  RETURN v_sid;
END $function$

CREATE OR REPLACE FUNCTION public.enforce_health_test_operation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE op public.health_test_operations;
BEGIN
IF NOT EXISTS(SELECT 1 FROM public.health_test_release WHERE singleton AND enabled) THEN RETURN NEW; END IF;
IF current_setting('role',true) IS DISTINCT FROM 'service_role' THEN RAISE EXCEPTION 'Bu test sürümü güvenli izin doğrulamasını desteklemiyor. Teste başlamadan uygulamanızı güncelleyin.' USING ERRCODE='42501'; END IF;
SELECT * INTO op FROM public.health_test_operations WHERE id::text=current_setting('app.health_test_operation',true);
IF NOT FOUND OR op.user_id IS DISTINCT FROM NEW.patient_user_id OR op.test_id IS DISTINCT FROM NEW.test_id OR op.specialist_id IS DISTINCT FROM NEW.specialist_id OR op.withdrawn_at IS NOT NULL OR op.result_id IS NOT NULL OR now()>=op.expires_at THEN RAISE EXCEPTION 'verified health operation required' USING ERRCODE='42501'; END IF;
RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.extract_first_int(p_text text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  m text[];
  n integer := NULL;
BEGIN
  IF p_text IS NULL OR length(trim(p_text)) = 0 THEN
    RETURN NULL;
  END IF;
  -- capture first sequence of digits
  SELECT regexp_matches(p_text, '([0-9]+)') INTO m;
  IF m IS NOT NULL AND array_length(m,1) > 0 THEN
    BEGIN
      n := m[1]::integer;
    EXCEPTION WHEN others THEN
      n := NULL;
    END;
  END IF;
  RETURN n;
END;
$function$

CREATE OR REPLACE FUNCTION public.generate_unique_referral_code()
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_chars text := 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789'; -- karışıklığı önlemek için 0,1,O,I yok
  v_code text;
  v_exists boolean;
  v_attempt int := 0;
BEGIN
  LOOP
    v_code := '';
    FOR i IN 1..8 LOOP
      v_code := v_code || substr(v_chars, 1 + floor(random() * length(v_chars))::int, 1);
    END LOOP;

    SELECT EXISTS(SELECT 1 FROM public.specialist_referral_codes WHERE code = v_code) INTO v_exists;
    EXIT WHEN NOT v_exists;

    v_attempt := v_attempt + 1;
    IF v_attempt > 20 THEN
      RAISE EXCEPTION 'Could not generate unique referral code after 20 attempts';
    END IF;
  END LOOP;

  RETURN v_code;
END;
$function$

CREATE OR REPLACE FUNCTION public.get_my_referred_specialists()
 RETURNS TABLE(id uuid, name text, email text, created_at timestamp with time zone, is_active boolean)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_specialist_id uuid;
  v_code text;
BEGIN
  -- Identify the calling specialist
  SELECT s.id INTO v_specialist_id
  FROM public.specialists s
  WHERE s.user_id = auth.uid()
  LIMIT 1;

  IF v_specialist_id IS NULL THEN
    RETURN;
  END IF;

  -- Get this specialist's referral code
  SELECT src.code INTO v_code
  FROM public.specialist_referral_codes src
  WHERE src.specialist_id = v_specialist_id
  LIMIT 1;

  IF v_code IS NULL THEN
    RETURN;
  END IF;

  RETURN QUERY
  SELECT s.id, s.name, s.email, s.created_at, s.is_active
  FROM public.specialists s
  WHERE s.referral_signup_code = v_code
  ORDER BY s.created_at DESC;
END;
$function$

CREATE OR REPLACE FUNCTION public.guard_anonymous_appointment_burst()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE claims jsonb; phone text; email text; recent_count integer; hour_count integer;
BEGIN
  claims := coalesce(nullif(current_setting('request.jwt.claims',true),''),'{}')::jsonb;
  IF coalesce(claims->>'role',nullif(current_setting('request.jwt.claim.role',true),''),'') <> 'anon' THEN RETURN NEW; END IF;
  NEW.created_at := now();
  IF EXISTS (SELECT 1 FROM public.appointments WHERE id=NEW.id) THEN RETURN NEW; END IF;
  phone := right(regexp_replace(NEW.patient_phone,'[^0-9]','','g'),10);
  email := lower(trim(NEW.patient_email));
  IF length(phone)<10 OR email='' THEN RETURN NEW; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('appointment-contact:'||phone||':'||email,0));
  SELECT count(*) FILTER (WHERE a.created_at >= now()-interval '10 minutes'),count(*) INTO recent_count,hour_count
    FROM public.appointments a WHERE a.created_at >= now()-interval '1 hour'
      AND right(regexp_replace(a.patient_phone,'[^0-9]','','g'),10)=phone AND lower(trim(a.patient_email))=email;
  IF recent_count>=6 OR hour_count>=20 THEN
    RAISE EXCEPTION 'appointment_retry_later' USING ERRCODE='P0001';
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.guard_appointment_slot()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE raw jsonb; slots jsonb; day_key text;
BEGIN
  IF TG_OP = 'UPDATE' AND NEW.status = 'cancelled' THEN RETURN NEW; END IF;
  IF NEW.specialist_id IS NULL THEN RETURN NEW; END IF;
  IF TG_OP = 'UPDATE' AND NEW.status IS NOT DISTINCT FROM OLD.status
     AND NEW.specialist_id IS NOT DISTINCT FROM OLD.specialist_id
     AND NEW.appointment_date IS NOT DISTINCT FROM OLD.appointment_date
     AND NEW.appointment_time IS NOT DISTINCT FROM OLD.appointment_time THEN RETURN NEW; END IF;
  SELECT available_time_slots::jsonb INTO raw FROM public.specialists WHERE id = NEW.specialist_id FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION 'appointment_specialist_unknown' USING ERRCODE='P0001'; END IF;
  PERFORM pg_advisory_xact_lock(hashtext(NEW.specialist_id::text || NEW.appointment_date::text || NEW.appointment_time::text));
  IF (TG_OP = 'INSERT' OR NEW.appointment_date IS DISTINCT FROM OLD.appointment_date
      OR NEW.appointment_time IS DISTINCT FROM OLD.appointment_time)
     AND (NEW.appointment_date + NEW.appointment_time) < (now() AT TIME ZONE 'Europe/Istanbul') THEN
    RAISE EXCEPTION 'appointment_slot_in_past' USING ERRCODE='P0001';
  END IF;
  day_key := to_char(NEW.appointment_date, 'YYYY-MM-DD');
  IF jsonb_typeof(raw) = 'object' AND raw ? 'default' THEN
    slots := CASE WHEN (raw->'dates') ? day_key THEN raw->'dates'->day_key ELSE raw->'default' END;
  ELSIF jsonb_typeof(raw) = 'array' AND jsonb_array_length(raw) > 0 THEN slots := raw;
  ELSE slots := '["09:30","10:00","10:30","11:00","11:30","12:00","12:30","13:00","13:30","14:00","14:30","15:00","15:30","16:00","16:30","17:00","17:30","18:00","18:30","19:00","19:30","20:00","20:30","21:00","21:30","22:00","22:30","23:00","23:30","00:00"]'::jsonb;
  END IF;
  IF jsonb_typeof(slots) IS DISTINCT FROM 'array' OR NOT (slots ? to_char(NEW.appointment_time,'HH24:MI'))
     OR extract(second from NEW.appointment_time) <> 0 THEN
    RAISE EXCEPTION 'appointment_slot_unavailable' USING ERRCODE='P0001';
  END IF;
  IF EXISTS (SELECT 1 FROM public.appointments a WHERE a.specialist_id=NEW.specialist_id
      AND a.appointment_date=NEW.appointment_date AND a.appointment_time=NEW.appointment_time
      AND a.status='confirmed' AND a.id<>NEW.id) THEN
    RAISE EXCEPTION 'appointment_slot_taken' USING ERRCODE='P0001';
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.guard_payment_client_writes()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE privileged boolean;
BEGIN
  privileged := COALESCE(auth.role() = 'service_role',false)
    OR (session_user = 'postgres' AND current_setting('role',true) IN ('none','postgres'))
    OR (auth.uid() IS NOT NULL AND CASE WHEN TG_TABLE_NAME='user_profiles' THEN public.is_admin_user() ELSE public.is_admin_or_staff_user() END);
  IF TG_TABLE_NAME = 'user_profiles' THEN
    IF TG_OP = 'INSERT' AND session_user = 'supabase_auth_admin'
      AND current_setting('role',true) IN ('none','supabase_auth_admin')
      AND NEW.role::text IN ('user','specialist','patient') AND NOT COALESCE(NEW.is_approved,false)
      AND EXISTS(SELECT 1 FROM auth.users u WHERE u.id=NEW.user_id AND lower(trim(u.email))=lower(trim(NEW.email))) THEN
      RETURN NEW;
    END IF;
  END IF;
  IF privileged THEN RETURN NEW; END IF;
  IF TG_TABLE_NAME = 'orders' THEN
    IF TG_OP <> 'INSERT' OR COALESCE(NEW.status,'pending') <> 'pending'
      OR NEW.approved_at IS NOT NULL OR NEW.approved_by IS NOT NULL
      OR NEW.payment_transaction_id IS NOT NULL
      OR NEW.subscription_reference_code IS NOT NULL
      OR NEW.iyzico_customer_reference_code IS NOT NULL
      OR COALESCE(NEW.payment_status,'pending') NOT IN ('pending','failed')
      OR COALESCE(NEW.invoice_sent,false) OR NEW.invoice_number IS NOT NULL THEN
      RAISE EXCEPTION 'payment_server_confirmation_required' USING ERRCODE='42501';
    END IF;
  ELSIF TG_TABLE_NAME = 'specialists' THEN
    IF TG_OP = 'INSERT' THEN
      IF NEW.user_id IS DISTINCT FROM auth.uid() OR auth.uid() IS NULL
        OR COALESCE(NEW.is_active,false)
        OR NEW.registration_source IS DISTINCT FROM 'self_registration'
        OR NOT EXISTS (SELECT 1 FROM auth.users u WHERE u.id=auth.uid() AND lower(trim(u.email))=lower(trim(NEW.email))) THEN
        RAISE EXCEPTION 'specialist_server_identity_required' USING ERRCODE='42501';
      END IF;
    ELSIF NEW.user_id IS DISTINCT FROM OLD.user_id
      OR NEW.email IS DISTINCT FROM OLD.email
      OR NEW.is_active IS DISTINCT FROM OLD.is_active
      OR NEW.registration_source IS DISTINCT FROM OLD.registration_source THEN
      RAISE EXCEPTION 'specialist_privileged_change_required' USING ERRCODE='42501';
    END IF;
  ELSIF TG_TABLE_NAME = 'user_profiles' THEN
    IF TG_OP='INSERT' THEN
      IF NEW.user_id IS DISTINCT FROM auth.uid() OR COALESCE(NEW.is_approved,false)
        OR NEW.role::text NOT IN ('user','specialist','patient') THEN
        RAISE EXCEPTION 'profile_privileged_change_required' USING ERRCODE='42501';
      END IF;
    ELSIF NEW.user_id IS DISTINCT FROM OLD.user_id OR NEW.role IS DISTINCT FROM OLD.role
      OR NEW.is_approved IS DISTINCT FROM OLD.is_approved THEN
      RAISE EXCEPTION 'profile_privileged_change_required' USING ERRCODE='42501';
    END IF;
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.health_test_commit(p_user uuid, p_operation uuid, p_capability_hash text, p_name text, p_contact text, p_answers jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE op public.health_test_operations; rid uuid; digest text; q record; a jsonb; total int:=0; answered int:=0;
BEGIN
IF current_setting('role',true) IS DISTINCT FROM 'service_role' OR p_user IS NULL THEN RAISE EXCEPTION 'verified server required' USING ERRCODE='42501'; END IF;
SELECT * INTO op FROM public.health_test_operations WHERE id=p_operation FOR UPDATE;
IF NOT FOUND OR op.user_id IS DISTINCT FROM p_user OR op.capability_hash IS DISTINCT FROM p_capability_hash THEN RAISE EXCEPTION 'operation denied' USING ERRCODE='42501'; END IF;
IF p_answers IS NULL OR jsonb_typeof(p_answers)<>'object' OR octet_length(p_answers::text)>65536 OR length(trim(COALESCE(p_name,''))) NOT BETWEEN 1 AND 200 OR length(trim(COALESCE(p_contact,''))) NOT BETWEEN 1 AND 254 THEN RAISE EXCEPTION 'invalid input'; END IF;
digest:=encode(sha256(convert_to(jsonb_build_array(p_name,p_contact,p_answers)::text,'UTF8')),'hex');
IF op.result_id IS NOT NULL THEN IF op.payload_hash IS DISTINCT FROM digest THEN RAISE EXCEPTION 'operation payload conflict'; END IF; RETURN op.result_id; END IF;
IF op.withdrawn_at IS NOT NULL OR now()>=op.expires_at OR NOT EXISTS(SELECT 1 FROM public.health_test_release WHERE singleton AND enabled) OR NOT EXISTS(SELECT 1 FROM public.health_test_consent_events WHERE operation_id=op.id AND user_id=p_user AND purpose='health_test' AND action='grant' AND document_hash=op.consent_hash) THEN RAISE EXCEPTION 'valid test consent required'; END IF;
IF NOT EXISTS(SELECT 1 FROM public.tests t WHERE t.id=op.test_id AND t.is_active AND (t.specialist_id=op.specialist_id OR EXISTS(SELECT 1 FROM public.specialist_tests st WHERE st.test_id=t.id AND st.specialist_id=op.specialist_id AND st.is_enabled))) OR NOT EXISTS(SELECT 1 FROM public.specialists WHERE id=op.specialist_id AND is_active) THEN RAISE EXCEPTION 'test mapping changed'; END IF;
IF EXISTS(SELECT 1 FROM jsonb_object_keys(p_answers) k WHERE NOT EXISTS(SELECT 1 FROM public.test_questions WHERE test_id=op.test_id AND id::text=k)) THEN RAISE EXCEPTION 'unknown answer'; END IF;
FOR q IN SELECT * FROM public.test_questions WHERE test_id=op.test_id ORDER BY step_number LOOP
 total:=total+1; a:=p_answers->q.id::text;
 IF q.is_required AND (a IS NULL OR a='null'::jsonb OR a='""'::jsonb) THEN RAISE EXCEPTION 'required answer'; END IF;
 IF a IS NOT NULL AND a<>'null'::jsonb THEN
 answered:=answered+1;
 IF q.question_type='multiple_choice' THEN IF jsonb_typeof(a)<>'string' OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(q.options) x WHERE x=a OR x->>'text'=a#>>'{}' OR x->>'value'=a#>>'{}') THEN RAISE EXCEPTION 'invalid option'; END IF;
 ELSIF q.question_type='scale' THEN IF jsonb_typeof(a)<>'number' OR (a#>>'{}')::numeric NOT BETWEEN 1 AND 10 THEN RAISE EXCEPTION 'invalid scale'; END IF;
 ELSIF q.question_type='text' THEN IF jsonb_typeof(a)<>'string' OR length(a#>>'{}')>4000 THEN RAISE EXCEPTION 'invalid text'; END IF;
 ELSE RAISE EXCEPTION 'unsupported question type'; END IF;
 END IF;
END LOOP;
IF total=0 THEN RAISE EXCEPTION 'empty test'; END IF;
PERFORM set_config('app.health_test_operation',op.id::text,true);
INSERT INTO public.test_results(test_id,specialist_id,patient_user_id,patient_name,patient_email,answers,results,status) VALUES(op.test_id,op.specialist_id,p_user,p_name,p_contact,p_answers,jsonb_build_object('answeredQuestions',answered,'totalQuestions',total,'completionRate',round(answered*100.0/total),'interpretation','specialist_review_required'),'completed') RETURNING id INTO rid;
UPDATE public.health_test_operations SET result_id=rid,payload_hash=digest,updated_at=now() WHERE id=op.id;
RETURN rid;
END $function$

CREATE OR REPLACE FUNCTION public.health_test_prepare(p_user uuid, p_test uuid, p_specialist uuid, p_capability_hash text, p_version text, p_disclosure_hash text, p_consent_hash text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE doc public.health_test_documents; t public.tests; sid uuid; op uuid;
BEGIN
IF current_setting('role',true) IS DISTINCT FROM 'service_role' OR p_user IS NULL THEN RAISE EXCEPTION 'verified server required' USING ERRCODE='42501'; END IF;
IF NOT EXISTS(SELECT 1 FROM public.health_test_release WHERE singleton AND enabled) THEN RAISE EXCEPTION 'health release unavailable'; END IF;
IF p_capability_hash IS NULL OR p_capability_hash !~ '^[a-f0-9]{64}$' THEN RAISE EXCEPTION 'invalid capability'; END IF;
SELECT * INTO doc FROM public.health_test_documents WHERE version=p_version AND legal_approved_at IS NOT NULL AND published_at<=now() FOR SHARE;
IF NOT FOUND OR p_disclosure_hash IS DISTINCT FROM encode(sha256(convert_to(doc.disclosure,'UTF8')),'hex') OR p_consent_hash IS DISTINCT FROM encode(sha256(convert_to(doc.consent,'UTF8')),'hex') THEN RAISE EXCEPTION 'approved document required'; END IF;
SELECT * INTO t FROM public.tests WHERE id=p_test AND is_active FOR SHARE;
IF NOT FOUND THEN RAISE EXCEPTION 'test unavailable'; END IF;
sid:=COALESCE(p_specialist,t.specialist_id);
IF sid IS NULL OR NOT EXISTS(SELECT 1 FROM public.specialists WHERE id=sid AND is_active) OR NOT (t.specialist_id=sid OR EXISTS(SELECT 1 FROM public.specialist_tests WHERE test_id=p_test AND specialist_id=sid AND is_enabled)) THEN RAISE EXCEPTION 'test specialist mismatch'; END IF;
INSERT INTO public.health_test_operations(user_id,test_id,specialist_id,capability_hash,document_version,disclosure_hash,consent_hash) VALUES(p_user,p_test,sid,p_capability_hash,p_version,p_disclosure_hash,p_consent_hash) RETURNING id INTO op;
INSERT INTO public.health_test_consent_events(operation_id,user_id,purpose,action,document_version,document_hash,document_text) VALUES(op,p_user,'test_disclosure','acknowledge',doc.version,p_disclosure_hash,doc.disclosure),(op,p_user,'health_test','grant',doc.version,p_consent_hash,doc.consent);
RETURN op;
END $function$

CREATE OR REPLACE FUNCTION public.health_test_withdraw(p_user uuid, p_operation uuid, p_capability_hash text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE op public.health_test_operations;
BEGIN
IF current_setting('role',true) IS DISTINCT FROM 'service_role' OR p_user IS NULL THEN RAISE EXCEPTION 'verified server required' USING ERRCODE='42501'; END IF;
SELECT * INTO op FROM public.health_test_operations WHERE id=p_operation FOR UPDATE;
IF NOT FOUND OR op.user_id IS DISTINCT FROM p_user OR op.capability_hash IS DISTINCT FROM p_capability_hash THEN RAISE EXCEPTION 'operation denied' USING ERRCODE='42501'; END IF;
IF op.withdrawn_at IS NOT NULL THEN RETURN true; END IF;
INSERT INTO public.health_test_consent_events(operation_id,user_id,purpose,action,document_version,document_hash,document_text) SELECT op.id,op.user_id,'health_test','withdraw',document_version,document_hash,document_text FROM public.health_test_consent_events WHERE operation_id=op.id AND purpose='health_test' AND action='grant';
IF NOT FOUND THEN RAISE EXCEPTION 'grant evidence missing'; END IF;
UPDATE public.health_test_operations SET withdrawn_at=now(),updated_at=now() WHERE id=op.id;
RETURN true;
END $function$

CREATE OR REPLACE FUNCTION public.link_partner_user(p_partner_id uuid, p_email text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id uuid;
BEGIN
  IF NOT public.is_admin_or_staff() THEN
    RAISE EXCEPTION 'Yetkisiz';
  END IF;

  SELECT up.user_id INTO v_user_id
  FROM public.user_profiles up
  WHERE lower(up.email) = lower(trim(p_email))
    AND up.role = 'partner'
  LIMIT 1;

  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Bu e-posta ile partner rolünde kullanıcı bulunamadı';
  END IF;

  UPDATE public.partners
  SET user_id = v_user_id, updated_at = NOW()
  WHERE id = p_partner_id;

  RETURN true;
END;
$function$

CREATE OR REPLACE FUNCTION public.mark_paid_month_on_order_approval()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_automatic_order RECORD;
  v_subscription_month integer;
  v_current_paid_months integer[];
BEGIN
  -- Sadece status approved veya completed olduğunda çalış
  IF NEW.status IN ('approved', 'completed') AND OLD.status NOT IN ('approved', 'completed') THEN
    v_subscription_month := COALESCE(NEW.subscription_month, 1);

    -- Email ile automatic_orders tablosunda müşteriyi bul
    SELECT id, paid_months INTO v_automatic_order
    FROM public.automatic_orders
    WHERE customer_email = NEW.customer_email
    LIMIT 1;

    IF v_automatic_order.id IS NOT NULL THEN
      v_current_paid_months := COALESCE(v_automatic_order.paid_months, ARRAY[]::integer[]);

      -- Eğer bu ay henüz işaretlenmemişse ekle
      IF NOT (v_subscription_month = ANY(v_current_paid_months)) THEN
        UPDATE public.automatic_orders
        SET paid_months = array_sort(array_append(v_current_paid_months, v_subscription_month)),
            updated_at = NOW()
        WHERE id = v_automatic_order.id;
      END IF;
    END IF;
  END IF;

  RETURN NEW;
END;
$function$

