CREATE OR REPLACE FUNCTION public.protect_user_profile_privileges()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  is_privileged boolean;
BEGIN
  -- Server-side / service role contexts have no auth.uid(); let them through
  IF auth.uid() IS NULL THEN
    RETURN NEW;
  END IF;

  is_privileged := public.is_admin_or_staff_user();

  IF is_privileged THEN
    RETURN NEW;
  END IF;

  IF TG_OP = 'INSERT' THEN
    IF NEW.role IS NULL OR NEW.role::text IN ('admin', 'staff', 'legal', 'muhasebe') THEN
      NEW.role := 'specialist'::public.user_role;
    END IF;
    NEW.is_approved := false;
    RETURN NEW;
  END IF;

  -- UPDATE by a non-privileged user: role and approval are immutable
  NEW.role := OLD.role;
  NEW.is_approved := OLD.is_approved;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.record_failed_admin_login(p_email text, p_ip_address text DEFAULT NULL::text)
 RETURNS TABLE(is_now_blocked boolean, blocked_until timestamp with time zone, attempts_remaining integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_record RECORD;
  v_new_count INTEGER;
  v_blocked_until TIMESTAMPTZ;
BEGIN
  -- Try to get existing record
  SELECT * INTO v_record 
  FROM public.admin_login_attempts 
  WHERE email = LOWER(p_email);

  IF NOT FOUND THEN
    -- First failed attempt
    INSERT INTO public.admin_login_attempts (email, ip_address, attempt_count, last_attempt_at)
    VALUES (LOWER(p_email), p_ip_address, 1, NOW());

    RETURN QUERY SELECT false, NULL::TIMESTAMPTZ, 2;
    RETURN;
  END IF;

  -- Check if already blocked
  IF v_record.is_blocked AND v_record.blocked_until > NOW() THEN
    RETURN QUERY SELECT true, v_record.blocked_until, 0;
    RETURN;
  END IF;

  -- Increment attempt count
  v_new_count := v_record.attempt_count + 1;

  -- Check if should be blocked (3 failed attempts)
  IF v_new_count >= 3 THEN
    v_blocked_until := NOW() + INTERVAL '3 hours';

    UPDATE public.admin_login_attempts 
    SET attempt_count = v_new_count,
        is_blocked = true,
        blocked_until = v_blocked_until,
        ip_address = COALESCE(p_ip_address, ip_address),
        last_attempt_at = NOW()
    WHERE email = LOWER(p_email);

    RETURN QUERY SELECT true, v_blocked_until, 0;
    RETURN;
  END IF;

  -- Just increment count
  UPDATE public.admin_login_attempts 
  SET attempt_count = v_new_count,
      ip_address = COALESCE(p_ip_address, ip_address),
      last_attempt_at = NOW()
  WHERE email = LOWER(p_email);

  RETURN QUERY SELECT false, NULL::TIMESTAMPTZ, (3 - v_new_count)::INTEGER;
END;
$function$

CREATE OR REPLACE FUNCTION public.register_partner_referral(p_referral_code text, p_specialist_user_id uuid, p_specialist_email text, p_specialist_name text, p_specialist_phone text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_partner_id uuid;
  v_commission numeric;
  v_id uuid;
  v_norm text;
BEGIN
  v_norm := public.normalize_ref_code(p_referral_code);

  IF v_norm IS NULL OR length(v_norm) < 3 THEN
    RETURN NULL;
  END IF;

  -- 1) Tam normalize eşleşme (kod veya isim)
  SELECT id, commission_per_signup INTO v_partner_id, v_commission
  FROM public.partners
  WHERE is_active = true
    AND (public.normalize_ref_code(referral_code) = v_norm
      OR public.normalize_ref_code(name) = v_norm)
  LIMIT 1;

  -- 2) Kırpılmış / uzatılmış kodlar için önek eşleşmesi
  IF v_partner_id IS NULL THEN
    SELECT id, commission_per_signup INTO v_partner_id, v_commission
    FROM public.partners
    WHERE is_active = true
      AND (
        public.normalize_ref_code(referral_code) LIKE v_norm || '%'
        OR v_norm LIKE public.normalize_ref_code(referral_code) || '%'
        OR public.normalize_ref_code(name) LIKE v_norm || '%'
        OR v_norm LIKE public.normalize_ref_code(name) || '%'
      )
    ORDER BY length(public.normalize_ref_code(referral_code)) DESC
    LIMIT 1;
  END IF;

  IF v_partner_id IS NULL THEN
    RETURN NULL;
  END IF;

  INSERT INTO public.partner_referrals (
    partner_id, specialist_user_id, specialist_email, specialist_name,
    specialist_phone, commission_amount, commission_status
  )
  VALUES (
    v_partner_id, p_specialist_user_id, lower(p_specialist_email), p_specialist_name,
    p_specialist_phone, COALESCE(v_commission, 1000), 'pending'
  )
  ON CONFLICT (partner_id, specialist_email) DO UPDATE
    SET specialist_user_id = COALESCE(EXCLUDED.specialist_user_id, public.partner_referrals.specialist_user_id),
        specialist_name = COALESCE(EXCLUDED.specialist_name, public.partner_referrals.specialist_name),
        specialist_phone = COALESCE(EXCLUDED.specialist_phone, public.partner_referrals.specialist_phone),
        updated_at = NOW()
  RETURNING id INTO v_id;

  RETURN v_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.reject_blocked_phone()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  digits text;
  last10 text;
  raw text;
  v_ip text;
BEGIN
  v_ip := public.client_ip_from_headers();
  IF (NEW.ip_address IS NULL OR btrim(coalesce(NEW.ip_address, '')) = '') AND v_ip IS NOT NULL THEN
    NEW.ip_address := v_ip;
  END IF;

  IF TG_OP <> 'INSERT' THEN
    RETURN NEW;
  END IF;

  raw := COALESCE(NEW.patient_phone, '');
  IF raw = '' THEN
    RETURN NEW;
  END IF;
  digits := regexp_replace(raw, '\D', '', 'g');
  last10 := right(digits, 10);

  IF last10 IN ('5383254444', '5308443006', '5541582878', '5399572171') THEN
    RAISE EXCEPTION 'blocked_visitor: bu telefon numarasi ile islem yapilamaz';
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.reject_blocked_phone_lead()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  digits text;
  last10 text;
  v_ip text;
  v_blocked boolean := false;
BEGIN
  v_ip := public.client_ip_from_headers();
  IF (NEW.ip_address IS NULL OR btrim(coalesce(NEW.ip_address, '')) = '') AND v_ip IS NOT NULL THEN
    NEW.ip_address := v_ip;
  END IF;

  IF TG_OP <> 'INSERT' THEN
    RETURN NEW;
  END IF;

  digits := regexp_replace(COALESCE(NEW.phone, ''), '\D', '', 'g');
  last10 := right(digits, 10);

  IF last10 IN ('5383254444', '5308443006', '5541582878', '5399572171') THEN
    v_blocked := true;
  END IF;

  IF NOT v_blocked THEN
    SELECT EXISTS (
      SELECT 1 FROM public.blocked_visitors bv
      WHERE (bv.full_name IS NOT NULL
             AND btrim(bv.full_name) <> ''
             AND lower(regexp_replace(bv.full_name, '\s+', ' ', 'g'))
               = lower(regexp_replace(btrim(coalesce(NEW.full_name, '')), '\s+', ' ', 'g')))
         OR (bv.phone IS NOT NULL
             AND public.normalize_phone_digits(bv.phone) <> ''
             AND public.normalize_phone_digits(bv.phone) = public.normalize_phone_digits(NEW.phone))
         OR (bv.ip_address IS NOT NULL AND btrim(bv.ip_address) <> ''
             AND NEW.ip_address IS NOT NULL AND btrim(NEW.ip_address) <> ''
             AND bv.ip_address = NEW.ip_address)
    ) INTO v_blocked;
  END IF;

  IF v_blocked THEN
    RAISE EXCEPTION 'blocked_visitor: bu bilgilerle basvuru yapilamaz';
  END IF;

  RETURN NEW;
END;
$function$

