CREATE OR REPLACE FUNCTION public.restore_from_backup(p_backup_id bigint, p_table_name text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_backup_timestamp timestamptz;
  v_backup_suffix text;
  v_tables_to_restore text[];
  v_table text;
BEGIN
  IF NOT public.is_admin_user() THEN
    RAISE EXCEPTION 'Forbidden: admin role required';
  END IF;

  -- Get backup info
  SELECT backup_timestamp, tables_backed_up
  INTO v_backup_timestamp, v_tables_to_restore
  FROM public.database_backups
  WHERE id = p_backup_id AND backup_status = 'completed';

  IF v_backup_timestamp IS NULL THEN
    RAISE EXCEPTION 'Backup not found or incomplete: %', p_backup_id;
  END IF;

  v_backup_suffix := EXTRACT(EPOCH FROM v_backup_timestamp)::bigint::text;

  -- Get list of tables to restore
  IF p_table_name IS NOT NULL THEN
    v_tables_to_restore := ARRAY[p_table_name];
  END IF;

  -- Restore each table
  FOREACH v_table IN ARRAY v_tables_to_restore
  LOOP
    IF EXISTS (
      SELECT 1 FROM information_schema.tables
      WHERE table_schema = 'public'
      AND table_name = 'backup_' || v_backup_suffix || '_' || v_table
    ) THEN
      EXECUTE 'TRUNCATE TABLE public.' || quote_ident(v_table) || ' CASCADE';
      EXECUTE 'INSERT INTO public.' || quote_ident(v_table) ||
              ' SELECT * FROM public.backup_' || v_backup_suffix || '_' || quote_ident(v_table);
      RAISE NOTICE 'Restored table: %', v_table;
    ELSE
      RAISE WARNING 'Backup table not found: backup_%_%', v_backup_suffix, v_table;
    END IF;
  END LOOP;

  RAISE NOTICE 'Database restore completed from backup: %', p_backup_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.send_contract_emails_on_approval()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  email_enabled BOOLEAN := false;
BEGIN
  -- Eğer e-posta gönderimi pasifse, sadece flag'i güncelle ve çık
  SELECT setting_value INTO email_enabled 
  FROM public.system_settings 
  WHERE setting_key = 'send_completion_emails' 
  LIMIT 1;

  IF NOT COALESCE(email_enabled, false) THEN
    NEW.contract_emails_sent = true;
    NEW.approved_at = NOW();
    RETURN NEW;
  END IF;

  -- Only send emails when order is approved for the first time
  IF NEW.status IN ('approved', 'completed') 
     AND OLD.status NOT IN ('approved', 'completed') 
     AND NEW.contract_emails_sent = false THEN

    -- SADECE İLK SİPARİŞLERDE E-POSTA GÖNDER (subscription_month = 1 veya is_first_order = true)
    IF (NEW.subscription_month = 1 OR NEW.is_first_order = true) THEN
      -- Call edge function to send contract emails with HTML content
      PERFORM net.http_post(
        url := 'https://irnfwewabogveofwemvg.supabase.co/functions/v1/send-order-documents-email',
        headers := '{"Content-Type": "application/json", "x-cron-secret": "07e465ec6d61a2a5c8d9475ea5151b0ba1cc8f257a3acd2566ac179b6cf1a51c", "Authorization": "Bearer [REDACTED]"}'::jsonb,
        body := jsonb_build_object(
          'customerEmail', NEW.customer_email,
          'customerName', NEW.customer_name,
          'packageName', NEW.package_name,
          'message', 'Sayın ' || NEW.customer_name || ', siparişiniz onaylanmıştır. Ön Bilgilendirme Formu ve Mesafeli Satış Sözleşmeniz aşağıda yer almaktadır.',
          'preInfoContent', COALESCE(NEW.pre_info_pdf_content, ''),
          'distanceSalesContent', COALESCE(NEW.distance_sales_pdf_content, '')
        )
      );
    END IF;

    -- Mark emails as sent and set approval time
    NEW.contract_emails_sent = true;
    NEW.approved_at = NOW();
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.set_specialist_slug()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  base_slug text;
  final_slug text;
  counter int := 0;
BEGIN
  -- Only set slug if it's not already set
  IF NEW.slug IS NULL OR NEW.slug = '' THEN
    base_slug := generate_specialist_slug(NEW.name);
    final_slug := base_slug;
    LOOP
      EXIT WHEN NOT EXISTS (SELECT 1 FROM public.specialists WHERE slug = final_slug AND id != NEW.id);
      counter := counter + 1;
      final_slug := base_slug || '-' || counter;
    END LOOP;
    NEW.slug := final_slug;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.settle_iyzico_payment(p_order_id uuid, p_payment_key text, p_subscription_ref text, p_customer_ref text, p_charge_ref text, p_amount numeric, p_currency text, p_paid_at timestamp with time zone, p_source text, p_binding text, p_session_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE o public.orders%ROWTYPE; s public.payment_checkout_sessions%ROWTYPE; prior uuid;
BEGIN
  IF p_order_id IS NULL OR coalesce(p_payment_key,'') = '' OR coalesce(p_subscription_ref,'') = ''
     OR coalesce(p_customer_ref,'') = '' OR coalesce(p_charge_ref,'') = '' OR p_paid_at IS NULL
     OR p_amount IS NULL OR p_amount <= 0 THEN
    RETURN jsonb_build_object('outcome','rejected','reason','proof_incomplete');
  END IF;
  IF p_currency IS DISTINCT FROM 'TRY' THEN
    RETURN jsonb_build_object('outcome','rejected','reason','currency_mismatch');
  END IF;
  IF p_binding NOT IN ('checkout_session','subscription_ref','renewal_bound','legacy_renewal') THEN
    RETURN jsonb_build_object('outcome','rejected','reason','binding_not_allowed');
  END IF;

  SELECT * INTO o FROM public.orders WHERE id = p_order_id FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('outcome','rejected','reason','order_missing'); END IF;

  SELECT order_id INTO prior FROM public.payment_receipts WHERE payment_key = p_payment_key;
  IF FOUND THEN RETURN jsonb_build_object('outcome','duplicate','order_id',prior); END IF;
  IF EXISTS (SELECT 1 FROM public.payment_receipts WHERE order_id = p_order_id) THEN
    RETURN jsonb_build_object('outcome','duplicate','order_id',p_order_id);
  END IF;

  IF o.deleted_at IS NOT NULL OR o.status <> 'pending' THEN
    RETURN jsonb_build_object('outcome','rejected','reason','order_not_pending','order_id',o.id);
  END IF;
  IF abs(o.amount - p_amount) > 0.005 THEN
    RETURN jsonb_build_object('outcome','rejected','reason','amount_mismatch');
  END IF;
  IF o.subscription_reference_code IS NOT NULL AND o.subscription_reference_code <> p_subscription_ref THEN
    RETURN jsonb_build_object('outcome','rejected','reason','subscription_mismatch');
  END IF;

  IF p_session_id IS NOT NULL THEN
    SELECT * INTO s FROM public.payment_checkout_sessions WHERE id = p_session_id FOR UPDATE;
    IF NOT FOUND OR s.order_id <> p_order_id OR s.status NOT IN ('initialized')
       OR abs(s.expected_amount - p_amount) > 0.005 OR s.currency <> p_currency
       OR (s.subscription_reference_code IS NOT NULL AND s.subscription_reference_code <> p_subscription_ref) THEN
      RETURN jsonb_build_object('outcome','rejected','reason','session_mismatch');
    END IF;
  ELSIF p_binding = 'checkout_session' THEN
    RETURN jsonb_build_object('outcome','rejected','reason','session_required');
  ELSIF coalesce(o.is_first_order, true) THEN
    -- First purchases may only be settled through a server checkout session.
    RETURN jsonb_build_object('outcome','rejected','reason','first_order_requires_session');
  END IF;

  -- A charge made before this deployment may already have approved another order without a receipt.
  IF EXISTS (SELECT 1 FROM public.orders x WHERE x.id <> p_order_id AND x.status IN ('approved','completed')
       AND x.deleted_at IS NULL AND x.approved_at >= p_paid_at
       AND (x.subscription_reference_code = p_subscription_ref
            OR (p_binding = 'legacy_renewal' AND lower(x.customer_email) = lower(o.customer_email)))) THEN
    RETURN jsonb_build_object('outcome','duplicate','reason','charge_already_consumed');
  END IF;

  BEGIN
    INSERT INTO public.payment_receipts(payment_key, order_id, session_id, subscription_reference_code,
      customer_reference_code, charge_reference, amount, currency, paid_at, source, binding)
    VALUES (p_payment_key, p_order_id, p_session_id, p_subscription_ref, p_customer_ref, p_charge_ref,
      p_amount, p_currency, p_paid_at, p_source, p_binding);
    IF p_session_id IS NOT NULL THEN
      UPDATE public.payment_checkout_sessions SET status = 'settled', settled_at = now(), updated_at = now(),
        subscription_reference_code = p_subscription_ref, customer_reference_code = p_customer_ref
      WHERE id = p_session_id;
    END IF;
  EXCEPTION WHEN unique_violation THEN
    RETURN jsonb_build_object('outcome','duplicate','reason','unique_receipt');
  END;

  UPDATE public.orders SET status = 'approved', approved_at = now(), payment_method = 'credit_card',
    payment_status = 'success', payment_transaction_id = p_subscription_ref,
    subscription_reference_code = p_subscription_ref, iyzico_customer_reference_code = p_customer_ref,
    updated_at = now()
  WHERE id = p_order_id AND status = 'pending';

  UPDATE public.automatic_orders SET subscription_reference_code = p_subscription_ref,
    iyzico_customer_reference_code = p_customer_ref
  WHERE lower(customer_email) = lower(o.customer_email) AND subscription_reference_code IS NULL;

  RETURN jsonb_build_object('outcome','applied','order_id',p_order_id);
END $function$

CREATE OR REPLACE FUNCTION public.sync_specialist_amount_to_customers()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.email IS NULL OR NEW.email = '' THEN
    RETURN NEW;
  END IF;
  IF COALESCE(OLD.package_price, -1) IS DISTINCT FROM COALESCE(NEW.package_price, -1) THEN
    UPDATE public.automatic_orders
    SET amount = COALESCE(NEW.package_price, 3000),
        updated_at = NOW()
    WHERE customer_email = NEW.email;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.trigger_generate_instagram_posts()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  service_key TEXT;
  fn_url TEXT := 'https://irnfwewabogveofwemvg.supabase.co/functions/v1/generate-specialist-instagram-posts';
BEGIN
  -- only when becoming active
  IF NEW.is_active IS NOT TRUE THEN
    RETURN NEW;
  END IF;
  IF TG_OP = 'UPDATE' AND OLD.is_active IS TRUE THEN
    RETURN NEW;
  END IF;

  -- skip if already ready
  IF EXISTS (
    SELECT 1 FROM public.specialist_instagram_posts
    WHERE specialist_id = NEW.id AND status = 'ready'
  ) THEN
    RETURN NEW;
  END IF;

  -- insert pending row
  INSERT INTO public.specialist_instagram_posts (specialist_id, status)
  VALUES (NEW.id, 'pending')
  ON CONFLICT (specialist_id) DO UPDATE SET status = 'pending', error_message = NULL;

  -- fire-and-forget edge function (via pg_net if available)
  BEGIN
    PERFORM net.http_post(
      url := fn_url,
      headers := jsonb_build_object(
        'Content-Type', 'application/json'
      ),
      body := jsonb_build_object('specialistId', NEW.id)
    );
  EXCEPTION WHEN OTHERS THEN
    -- pg_net not available or failed; admin can retry from UI
    NULL;
  END;

  RETURN NEW;
END;
$function$
